namespace ghidra.app.plugin.core.label;





using docking.action;
using ghidra.app.context;
using ghidra.app.context;
using ghidra.program.model.symbol;

/**
 * <CODE>RemoveLabelAction</CODE> allows the user to remove a label.
 */
class RemoveLabelAction : ListingContextAction {
	private LabelMgrPlugin plugin;

	private static readonly string[] POPUP_PATH = new string[] { "Remove Label" };
	private static readonly KeyStroke KEYBINDING = KeyStroke.getKeyStroke(KeyEvent.VK_DELETE, 0);

	/**
	 * Creates a new instance of the action.
	 *
	 * @param plugin Label Manager Plugin instance
	 */
	RemoveLabelAction(LabelMgrPlugin plugin) : base("Remove Label", plugin.getName(), KeyBindingType.SHARED)
    {
		this.plugin = plugin;

		setPopupMenuData(new MenuData(POPUP_PATH, null, "Label"));
		setKeyBindingData(new KeyBindingData(KEYBINDING));

		setEnabled(true);
	}

	/* @Override */
	public void actionPerformed(ListingActionContext context) {
		plugin.removeLabelCallback(context);
	}

	/* @Override */
	public bool isEnabledForContext(ListingActionContext context) {
		return !plugin.isOnExternalReference(context) && isOnSymbol(context);
	}

	bool isOnSymbol(ListingActionContext context) {
		Symbol s = plugin.getSymbol(context);
		if (s == null) {
			return false;
		}
		SymbolType type = s.getSymbolType();
		return (type == SymbolType.LABEL && !s.isDynamic()) ||
			(type == SymbolType.FUNCTION && s.getSource() != SourceType.DEFAULT);
	}

	/**
	 * @see DockingAction#dispose()
	 */
	/* @Override */
	public void dispose() {
		base.dispose();
		plugin = null;
	}

}
